package com.aicommerce.platform.delivery.domain;
import java.util.UUID; import com.aicommerce.platform.common.persistence.MutableEntity; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="platform_ads") public class PlatformAd extends MutableEntity {
 @Id @Column(name="platform_ad_uuid",updatable=false) private UUID platformAdUuid; @Column(name="platform_ad_set_uuid",updatable=false) private UUID platformAdSetUuid; @Column(name="platform_account_uuid",updatable=false) private UUID platformAccountUuid; @Column(name="product_uuid",updatable=false) private UUID productUuid; @Column(name="asset_uuid",updatable=false) private UUID assetUuid; @Column(name="generation_output_uuid",updatable=false) private UUID generationOutputUuid; @Column(name="review_decision_uuid",updatable=false) private UUID reviewDecisionUuid; @JdbcTypeCode(SqlTypes.CHAR) @Column(name="approved_checksum_sha256",updatable=false,columnDefinition="char(64)") private String approvedChecksumSha256; @Column(name="creative_mapping_key",updatable=false) private String creativeMappingKey; @Enumerated(EnumType.STRING) @Column(name="desired_state") private PlatformDesiredState desiredState; @Enumerated(EnumType.STRING) @Column(name="observed_state") private PlatformObservedState observedState; @Column(name="external_id") private String externalId;
 protected PlatformAd(){} public UUID getPlatformAdUuid(){return platformAdUuid;} public UUID getAssetUuid(){return assetUuid;} public String getApprovedChecksumSha256(){return approvedChecksumSha256;}
}
